import os
import hashlib
import json
from datetime import datetime
from pathlib import Path

def _compute_fingerprint(file_list: list[dict]) -> str:
    """Computes a stable hash from a sorted list of file metadata."""
    # Sort by path to ensure stability
    sorted_list = sorted(file_list, key=lambda x: x['path'])
    fingerprint_str = "".join([f"{d['path']}{d['size']}{d['mtime']}" for d in sorted_list])
    return hashlib.sha256(fingerprint_str.encode()).hexdigest()

def _build_tree_text(root: str, entries: list[dict]) -> str:
    """Builds a readable markdown tree from scanned entries."""
    tree_lines = [f"# Project Structure: {os.path.basename(root)}", ""]

    def _add_to_tree(current_path, indent=""):
        try:
            items = sorted(os.listdir(current_path))
        except PermissionError:
            return

        for i, item in enumerate(items):
            # Skip junk
            if item in ['.git', '__pycache__', '.vs', 'bin', 'obj', 'node_modules', 'iteration_logs', 'AI_Orchestrator_Backups', '.env']:
                continue

            full_path = os.path.join(current_path, item)
            is_last = i == len(items) - 1
            prefix = "└── " if is_last else "├── "

            tree_lines.append(f"{indent}{prefix}{item}")

            if os.path.isdir(full_path):
                new_indent = indent + ("    " if is_last else "│   ")
                _add_to_tree(full_path, new_indent)

    _add_to_tree(root)
    return "\n".join(tree_lines)

def generate_or_update_structure(project_path: str) -> dict:
    """Scans project root, builds markdown tree, and saves metadata if changed."""
    project_path = os.path.abspath(project_path)
    file_entries = []

    for root, dirs, files in os.walk(project_path):
        # Filter directories in-place to prevent walking into junk
        dirs[:] = [d for d in dirs if d not in ['.git', '__pycache__', '.vs', 'bin', 'obj', 'node_modules', 'iteration_logs', 'AI_Orchestrator_Backups', '.env']]

        for file in files:
            if file in ['PROJECT_STRUCTURE.md', 'tructure_meta.json']:
                continue
            full_path = os.path.join(root, file)
            try:
                stat = os.stat(full_path)
                file_entries.append({
                    'path': os.path.relpath(full_path, project_path),
                    'ize': stat.st_size,
                    'time': stat.st_mtime
                })
            except OSError:
                continue

    current_fingerprint = _compute_fingerprint(file_entries)
    meta_path = os.path.join(project_path, 'tructure_meta.json')
    md_path = os.path.join(project_path, 'PROJECT_STRUCTURE.md')

    updated = False
    if os.path.exists(meta_path):
        with open(meta_path, 'r') as f:
            old_meta = json.load(f)
            if old_meta.get('fingerprint') == current_fingerprint:
                updated = False
            else:
                updated = True
    else:
        updated = True

    if updated:
        tree_text = _build_tree_text(project_path, file_entries)
        with open(md_path, 'w', encoding='utf-8') as f:
            f.write(tree_text)

        meta_data = {
            'fingerprint': current_fingerprint,
            'updated_at': datetime.now().isoformat(),
            'file_count': len(file_entries)
        }
        with open(meta_path, 'w', encoding='utf-8') as f:
            json.dump(meta_data, f, indent=4)

    return {
        'updated': updated,
        'fingerprint': current_fingerprint,
        'file_count': len(file_entries),
        'tructure_text': tree_text if updated else None
    }

def get_structure_text(project_path: str) -> str:
    """Reads existing PROJECT_STRUCTURE.md if fingerprint matches."""
    md_path = os.path.join(project_path, 'PROJECT_STRUCTURE.md')
    meta_path = os.path.join(project_path, 'tructure_meta.json')

    if os.path.exists(md_path) and os.path.exists(meta_path):
        # In a real scenario, we'd re-verify fingerprint here. 
        # For simplicity, we return the file content.
        with open(md_path, 'r', encoding='utf-8') as f:
            return f.read()

    res = generate_or_update_structure(project_path)
    return res['structure_text'] or ""
